package com.trampolim.api.education;

import java.util.*;
import org.springframework.beans.factory.annotation.*;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;

@RestController
@RequestMapping("/api/capacita/learning/inclusion")
@ConditionalOnProperty(name="trampolim.datasource.capacita.enabled",havingValue="true")
public class InclusionController {
    private final JdbcTemplate jdbc;private final LearningAccess access;
    @Value("${capacita.inclusion.closed-retention-days:90}")private int retentionDays=90;
    public InclusionController(@Qualifier("capacitaJdbcTemplate")JdbcTemplate jdbc,LearningAccess access){this.jdbc=jdbc;this.access=access;}
    public record Preferences(int fontPercent,boolean highContrast,boolean reducedMotion,boolean textSpacing,double playbackSpeed,boolean captions,boolean muted){}
    public record RequestInput(UUID clientKey,String message,boolean consent){}
    public record SupportReply(String status,String reply){}
    public record TeacherVerification(String email,String summary,String reference,boolean verified){}
    @GetMapping("/preferences")public Map<String,Object> preferences(@AuthenticationPrincipal String email){long id=access.account(email).id();var rows=jdbc.queryForList("SELECT font_percent AS \"fontPercent\",high_contrast AS \"highContrast\",reduced_motion AS \"reducedMotion\",text_spacing AS \"textSpacing\",playback_speed AS \"playbackSpeed\",captions,muted FROM student_accessibility_preferences WHERE user_id=?",id);return rows.isEmpty()?Map.of("saved",false):Map.of("saved",true,"preferences",rows.get(0));}
    @PutMapping("/preferences")@ResponseStatus(HttpStatus.NO_CONTENT)public void preferences(@AuthenticationPrincipal String email,@RequestBody Preferences p){long id=access.account(email).id();if(p==null||!Set.of(100,112,125,150).contains(p.fontPercent())||!Set.of(.75,1d,1.25,1.5,2d).contains(p.playbackSpeed()))bad("Preferências inválidas.");jdbc.update("INSERT INTO student_accessibility_preferences(user_id,font_percent,high_contrast,reduced_motion,text_spacing,playback_speed,captions,muted) VALUES (?,?,?,?,?,?,?,?) ON CONFLICT(user_id) DO UPDATE SET font_percent=EXCLUDED.font_percent,high_contrast=EXCLUDED.high_contrast,reduced_motion=EXCLUDED.reduced_motion,text_spacing=EXCLUDED.text_spacing,playback_speed=EXCLUDED.playback_speed,captions=EXCLUDED.captions,muted=EXCLUDED.muted,updated_at=CURRENT_TIMESTAMP",id,p.fontPercent(),p.highContrast(),p.reducedMotion(),p.textSpacing(),p.playbackSpeed(),p.captions(),p.muted());}
    @GetMapping("/requests")public List<Map<String,Object>> requests(@AuthenticationPrincipal String email,@RequestParam(defaultValue="false")boolean manage,@RequestParam(required=false)Long before){var user=manage?access.admin(email):access.account(email);var args=new ArrayList<Object>();String where=" WHERE r.id<?";args.add(before==null?Long.MAX_VALUE:before);if(!manage){where+=" AND r.student_id=?";args.add(user.id());}return jdbc.queryForList("SELECT r.id,r.message,r.reply,r.status,r.created_at,r.updated_at,u.full_name AS student_name FROM learning_support_requests r JOIN student_users u ON u.id=r.student_id"+where+" ORDER BY r.id DESC LIMIT 50",args.toArray());}
    @PostMapping("/requests")@Transactional("capacitaTransactionManager")public Map<String,Object> request(@AuthenticationPrincipal String email,@RequestBody RequestInput input){var user=access.account(email);if(input==null||input.clientKey()==null||!input.consent()||input.message()==null||input.message().isBlank()||input.message().length()>4000)bad("Descreva o apoio desejado e confirme o atendimento privado.");jdbc.queryForObject("SELECT id FROM student_users WHERE id=? FOR NO KEY UPDATE",Long.class,user.id());var existing=jdbc.queryForList("SELECT id,message FROM learning_support_requests WHERE student_id=? AND client_key=?",user.id(),input.clientKey());if(!existing.isEmpty()){if(!input.message().trim().equals(existing.get(0).get("message")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Envio já utilizado com outro conteúdo.");return Map.of("id",existing.get(0).get("id"));}if(jdbc.queryForObject("SELECT count(*) FROM learning_support_requests WHERE student_id=? AND created_at>CURRENT_TIMESTAMP-INTERVAL '1 hour'",Integer.class,user.id())>=5)throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Aguarde antes de abrir outro pedido de apoio.");long id=jdbc.queryForObject("INSERT INTO learning_support_requests(student_id,client_key,message) VALUES (?,?,?) RETURNING id",Long.class,user.id(),input.clientKey(),input.message().trim());audit(user.id(),user.id(),"SUPPORT_REQUESTED");return Map.of("id",id);}
    @PutMapping("/requests/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)@Transactional("capacitaTransactionManager")public void reply(@AuthenticationPrincipal String email,@PathVariable long id,@RequestBody SupportReply input){var admin=access.admin(email);if(input==null||!Set.of("OPEN","IN_PROGRESS","CLOSED").contains(Objects.toString(input.status(),""))||input.reply()==null||input.reply().length()>4000)bad("Resposta inválida.");if(jdbc.update("UPDATE learning_support_requests SET reply=?,status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?",input.reply().trim(),input.status(),id)==0)missing();audit(admin.id(),null,"SUPPORT_UPDATED");}
    @DeleteMapping("/requests/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)@Transactional("capacitaTransactionManager")public void delete(@AuthenticationPrincipal String email,@PathVariable long id){var user=access.account(email);if(jdbc.update("DELETE FROM learning_support_requests WHERE id=?"+(user.admin()?"":" AND student_id=?"),user.admin()?new Object[]{id}:new Object[]{id,user.id()})==0)missing();audit(user.id(),null,"SUPPORT_DELETED");}
    @GetMapping("/teachers")public List<Map<String,Object>> teachers(@AuthenticationPrincipal String email){access.account(email);return jdbc.queryForList("SELECT u.id,u.full_name AS name,v.public_summary,v.checked_at FROM learning_inclusive_teachers v JOIN student_users u ON u.id=v.user_id WHERE v.verified=TRUE AND u.account_status='ACTIVE' AND u.email_verified=TRUE AND EXISTS(SELECT 1 FROM learning_account_roles r WHERE r.user_id=u.id AND r.role IN ('TEACHER','ADMIN')) ORDER BY u.full_name LIMIT 100");}
    @PutMapping("/teachers")@ResponseStatus(HttpStatus.NO_CONTENT)@Transactional("capacitaTransactionManager")public void verifyTeacher(@AuthenticationPrincipal String email,@RequestBody TeacherVerification input){var admin=access.admin(email);if(input==null||input.email()==null||input.summary()==null||input.summary().isBlank()||input.summary().length()>1000||input.reference()==null||input.reference().isBlank()||input.reference().length()>1000)bad("Informe professor, resumo e referência da verificação manual.");var teacher=access.teacher(input.email().trim());if(teacher.id()==admin.id())bad("A verificação deve ser realizada por outro administrador educacional.");jdbc.update("INSERT INTO learning_inclusive_teachers(user_id,public_summary,verification_reference,verified,verified_by) VALUES (?,?,?,?,?) ON CONFLICT(user_id) DO UPDATE SET public_summary=EXCLUDED.public_summary,verification_reference=EXCLUDED.verification_reference,verified=EXCLUDED.verified,verified_by=EXCLUDED.verified_by,checked_at=CURRENT_TIMESTAMP",teacher.id(),input.summary().trim(),input.reference().trim(),input.verified(),admin.id());audit(admin.id(),teacher.id(),input.verified()?"INCLUSION_TEACHER_VERIFIED":"INCLUSION_TEACHER_REVOKED");}
    @Scheduled(fixedDelayString="${capacita.inclusion.cleanup-ms:3600000}")public void cleanup(){if(retentionDays>0)try{jdbc.update("DELETE FROM learning_support_requests WHERE status='CLOSED' AND updated_at<CURRENT_TIMESTAMP-(? * INTERVAL '1 day')",retentionDays);}catch(org.springframework.dao.DataAccessException ignored){/* Retry later; never expose requests to public endpoints. */}}
    private void audit(long actor,Long target,String event){jdbc.update("INSERT INTO learning_inclusion_audit(actor_id,target_id,event) VALUES (?,?,?)",actor,target,event);}
    private static void bad(String message){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,message);}private static void missing(){throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Pedido indisponível.");}
}
